CREATE TABLE IF NOT EXISTS "account_group_ratios" ("id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY, "account_id" INTEGER NOT NULL, "site_id" INTEGER NOT NULL, "group_name" TEXT NOT NULL, "multiplier" DOUBLE PRECISION NOT NULL, "refreshed_at" TEXT, "failed_attempts" INTEGER NOT NULL DEFAULT 0, "last_error" TEXT, "created_at" TEXT DEFAULT to_char(timezone('UTC', CURRENT_TIMESTAMP), 'YYYY-MM-DD HH24:MI:SS'), "updated_at" TEXT DEFAULT to_char(timezone('UTC', CURRENT_TIMESTAMP), 'YYYY-MM-DD HH24:MI:SS'), FOREIGN KEY ("account_id") REFERENCES "accounts"("id") ON DELETE CASCADE, FOREIGN KEY ("site_id") REFERENCES "sites"("id") ON DELETE CASCADE);
CREATE UNIQUE INDEX "account_group_ratios_account_site_group_unique" ON "account_group_ratios" ("account_id", "site_id", "group_name");
CREATE INDEX "account_group_ratios_account_site_idx" ON "account_group_ratios" ("account_id", "site_id");
CREATE INDEX "account_group_ratios_site_group_idx" ON "account_group_ratios" ("site_id", "group_name");
